// These are the Command Processor dword packet headers for high-frequency D3D12 APIs.
static const UINT32 D3D12XBOX_PACKET_DRAW_INDEXED_INSTANCED = 0x4004c200;
static const UINT32 D3D12XBOX_PACKET_DRAW_INSTANCED         = 0x4003c300;
static const UINT32 D3D12XBOX_PACKET_DISPATCH               = 0x4002c400;
