static const UINT32 D3D12XBOX_PACKET_SET_INDEX_BUFFER       = 0x4001b700;
static const UINT32 D3D12XBOX_PACKET_SET_STENCIL_REF        = 0xc000b800;
static const UINT32 D3D12XBOX_PACKET_SET_VERTEX_BUFFERS     = 0x3fffc600; // Encoded dword count of 0
static const UINT32 D3D12XBOX_PACKET_CLEAR_VERTEX_BUFFERS   = 0x4000c700;
static const UINT32 D3D12XBOX_PACKET_DISPATCH_X             = 0x4003cc00;
static const UINT32 D3D12XBOX_PACKET_DRAW_INDEXED_X         = 0x4004cd00;
static const UINT32 D3D12XBOX_PACKET_NOP                    = 0x80000000;
static const UINT32 D3D12XBOX_PACKET_NOP_WITH_COUNT         = 0xbffe1000; // Encoded total packet size of 0
static const UINT32 D3D12XBOX_PACKET_DISPATCH_MESH          = 0x4003d500;

// Fast path versions that don't handle shader memory a.k.a. 'shmem'
static const UINT32 D3D12XBOX_PACKET_DRAW_INSTANCED_NO_SHMEM            = 0x4003e600;
static const UINT32 D3D12XBOX_PACKET_DRAW_INDEXED_INSTANCED_NO_SHMEM    = 0x4004e700;
static const UINT32 D3D12XBOX_PACKET_DISPATCH_NO_SHMEM                  = 0x4002e800;

// Command Processor packets encode the dword count minus one at bit 16. The above packet
// header constants already have pre-built sizes for all the fixed size packets, and default
// counts for the variable-sized packets as noted:
static const UINT32 D3D12XBOX_PACKET_COUNT_SHIFT = 16;

// The SET_VERTEX_BUFFERS packet takes a qword for every vertex buffer where the GPU virtual
// address is in the low 48 bits and the stride, in bytes, in the high 16 bits:
static const UINT32 D3D12XBOX_SET_VERTEX_BUFFERS_STRIDE_SHIFT64 = 48;

