typedef enum TCP_PERFCOUNTER_SELECT : unsigned int {
    TCP_PERF_SEL_GATE_EN1                               = 0x00000000,  // TCP interface clocks are turned on. Not Windowed.
    TCP_PERF_SEL_GATE_EN2                               = 0x00000001,  // TCP core clocks are turned on. Not Windowed.
    TCP_PERF_SEL_TA_REQ                                 = 0x00000002,  // Total reqs from TA
    TCP_PERF_SEL_TA_REQ_STATE_READ                      = 0x00000003,  // Number of state reads (start of a wave instruction)
    TCP_PERF_SEL_TA_REQ_READ                            = 0x00000004,  // Total reqs from TA using read opcodes
    TCP_PERF_SEL_TA_REQ_WRITE                           = 0x00000005,  // Total reqs from TA using write opcodes
    TCP_PERF_SEL_TA_REQ_ATOMIC_WITH_RET                 = 0x00000006,  // Total reqs from TA using atomic with return opcodes
    TCP_PERF_SEL_TA_REQ_ATOMIC_WITHOUT_RET              = 0x00000007,  // Total reqs from TA using atomic without return opcodes
    TCP_PERF_SEL_TA_REQ_GL0_INV                         = 0x00000008,  // Total reqs from TA using GL0_INV opcode
    TCP_PERF_SEL_REQ                                    = 0x00000009,  // Total cache line accesses
    TCP_PERF_SEL_REQ_READ                               = 0x0000000a,  // Total cache read requests
    TCP_PERF_SEL_REQ_READ_HIT_EVICT                     = 0x0000000b,  // Total cache reads using HIT_EVICT policy
    TCP_PERF_SEL_REQ_READ_HIT_LRU                       = 0x0000000c,  // Total cache reads using HIT_LRU policy
    TCP_PERF_SEL_REQ_READ_MISS_EVICT                    = 0x0000000d,  // Total cache reads using MISS_EVICT policy
    TCP_PERF_SEL_REQ_WRITE                              = 0x0000000e,  // Total cache write requests
    TCP_PERF_SEL_REQ_WRITE_MISS_EVICT                   = 0x0000000f,  // Total cache writes using MISS_EVICT policy
    TCP_PERF_SEL_REQ_WRITE_MISS_LRU                     = 0x00000010,  // Total cache writes using MISS_LRU policy
    TCP_PERF_SEL_REQ_NON_READ                           = 0x00000011,  // Total cache non-read requests
    TCP_PERF_SEL_REQ_MISS                               = 0x00000012,  // Total cache requests that missed
    TCP_PERF_SEL_REQ_TAGBANK0                           = 0x00000013,  // Total cache requests for tag bank 0
    TCP_PERF_SEL_REQ_TAGBANK1                           = 0x00000014,  // Total cache requests for tag bank 1
    TCP_PERF_SEL_REQ_TAGBANK2                           = 0x00000015,  // Total cache requests for tag bank 2
    TCP_PERF_SEL_REQ_TAGBANK3                           = 0x00000016,  // Total cache requests for tag bank 3
    TCP_PERF_SEL_REQ_MISS_TAGBANK0                      = 0x00000017,  // Total cache requests that missed for tag bank 0
    TCP_PERF_SEL_REQ_MISS_TAGBANK1                      = 0x00000018,  // Total cache requests that missed for tag bank 1
    TCP_PERF_SEL_REQ_MISS_TAGBANK2                      = 0x00000019,  // Total cache requests that missed for tag bank 2
    TCP_PERF_SEL_REQ_MISS_TAGBANK3                      = 0x0000001a,  // Total cache requests that missed for tag bank 3
    TCP_PERF_SEL_GL1_REQ_READ                           = 0x0000001b,  // Total read requests to GL1.
    TCP_PERF_SEL_GL1_REQ_READ_128B                      = 0x0000001c,  // Total read requests to GL1 with 128B size.
    TCP_PERF_SEL_GL1_REQ_READ_64B                       = 0x0000001d,  // Total read requests to GL1 with 64B size.
    TCP_PERF_SEL_GL1_REQ_WRITE                          = 0x0000001e,  // Total write requests to GL1.
    TCP_PERF_SEL_GL1_REQ_ATOMIC_WITH_RET                = 0x0000001f,  // Total atomic with return requests to GL1.
    TCP_PERF_SEL_GL1_REQ_ATOMIC_WITHOUT_RET             = 0x00000020,  // Total atomic without return requests to GL1.
    TCP_PERF_SEL_GL1_READ_LATENCY                       = 0x00000021,  // Total latency for reads and atomics with return.  Not windowed.
    TCP_PERF_SEL_GL1_WRITE_LATENCY                      = 0x00000022,  // Total TC->GL1 request latency for reads and atomics with return. Not windowed.
    TCP_PERF_SEL_TCP_LATENCY                            = 0x00000023,  // Total TCP instruction latency (from first clock of instruction entering to first clock of instruction leaving), divide by TA_TCP_STATE_READ to average instruction latency.
    TCP_PERF_SEL_TCP_TA_REQ_STALL                       = 0x00000024,  // TCP stalls TA req interface.
    TCP_PERF_SEL_TA_TCP_REQ_STARVE                      = 0x00000025,  // TA starves TA req interface.  Not Windowed.
    TCP_PERF_SEL_TA_TCP_XNACK_STALL                     = 0x00000026,  // Total number of cycles TA stalled the TCP_TA_xnack interface.  Not Windowed.
    TCP_PERF_SEL_DATA_FIFO_STALL                        = 0x00000027,  // TPCP stalls TA req due to data fifo full
    TCP_PERF_SEL_LOD_STALL                              = 0x00000028,  // Per-element LOD stall (TCP supports one mip level per cycle)
    TCP_PERF_SEL_POWER_STALL                            = 0x00000029,  // Count of stalls due to power throttling
    TCP_PERF_SEL_ALLOC_STALL                            = 0x0000002a,  // Alloc stall on inflight cache line
    TCP_PERF_SEL_UNORDERED_MTYPE_STALL                  = 0x0000002b,  // Total stalls to maintain coherency for UC/CC mtype (GL2 unordered)
    TCP_PERF_SEL_READ_TAGCONFLICT_STALL                 = 0x0000002c,  // Tag conflict stall on a read
    TCP_PERF_SEL_WRITE_TAGCONFLICT_STALL                = 0x0000002d,  // Tag conflict stall on a write
    TCP_PERF_SEL_ATOMIC_TAGCONFLICT_STALL               = 0x0000002e,  // Tag conflict stall on an atomic
    TCP_PERF_SEL_LFIFO_STALL                            = 0x0000002f,  // Memory latency fifos full stall
    TCP_PERF_SEL_MEM_REQ_FIFO_STALL                     = 0x00000030,  // Stall due to memory request fifo full
    TCP_PERF_SEL_GL1_TCP_STALL                          = 0x00000031,  // TCP_GL1 request interface stalled by GL1
    TCP_PERF_SEL_TCP_GL1_STARVE                         = 0x00000032,  // TCP starves GL1 req interface.
    TCP_PERF_SEL_GL1_TCP_RDRET_STALL                    = 0x00000033,  // Write to cache stalled by read return from GL1.
    TCP_PERF_SEL_GL1_GRANT_READ_STALL                   = 0x00000034,  // Read from cache stalled due to GL1 write data bus grant
    TCP_PERF_SEL_GL1_PENDING_STALL                      = 0x00000035,  // Stall due to waiting for response from GL1
    TCP_PERF_SEL_OFIFO_INCOMPLETE_STALL                 = 0x00000036,  // Stall in ofifo due to waiting for incomplete (split) non-sampler instruction
    TCP_PERF_SEL_OFIFO_AGE_ORDER_STALL                  = 0x00000037,  // Stall in ofifo due to age order enforcement for incomplete instructions
    TCP_PERF_SEL_TD_DATA_CYCLE_STALL                    = 0x00000038,  // Read pipe stall due to TC_TD data interface cycling
    TCP_PERF_SEL_COMP_TEX_LOAD_STALL                    = 0x00000039,  // Read pipe stall due to block-compressed format load cycling
    TCP_PERF_SEL_READ_DATACONFLICT_STALL                = 0x0000003a,  // Read stall due to cache data bank conflict
    TCP_PERF_SEL_WRITE_DATACONFLICT_STALL               = 0x0000003b,  // Write stall due to cache data bank conflict
    TCP_PERF_SEL_TD_TCP_STALL                           = 0x0000003c,  // TD stalls TCP
    TCP_PERF_SEL_UTCL0_REQUEST                          = 0x0000003d,  // Total CLIENT_UTCL0 NORMAL requests
    TCP_PERF_SEL_UTCL0_TRANSLATION_MISS                 = 0x0000003e,  // Total UTCL0 translation misses
    TCP_PERF_SEL_UTCL0_TRANSLATION_HIT                  = 0x0000003f,  // Total UTCL0 translation hits
    TCP_PERF_SEL_UTCL0_PERMISSION_MISS                  = 0x00000040,  // Total UTCL0 permission misses
    TCP_PERF_SEL_UTCL0_SERIALIZATION_STALL              = 0x00000041,  // Total stalls due to serializing translation requests through the UTCL0.
    TCP_PERF_SEL_UTCL0_STALL_INFLIGHT_MAX               = 0x00000042,  // Total UTCL0 stalls due to inflight counter saturation
    TCP_PERF_SEL_UTCL0_STALL_LRU_INFLIGHT               = 0x00000043,  // Total UTCL0 stalls due to LRU cache line with traffic inflight
    TCP_PERF_SEL_UTCL0_STALL_MULTI_MISS                 = 0x00000044,  // Total UTCL0 stalls due to arbitrated multiple misses
    TCP_PERF_SEL_UTCL0_STALL_LFIFO_FULL                 = 0x00000045,  // Total UTCL0 latency hiding fifo full cycles
    TCP_PERF_SEL_UTCL0_STALL_MISSFIFO_FULL              = 0x00000046,  // Total UTCL0 stalls due to full miss fifo
    TCP_PERF_SEL_UTCL0_STALL_LFIFO_NOT_RES              = 0x00000047,  // Total UTCL0 stalls due to latency hiding fifo output waiting on translation responses
    TCP_PERF_SEL_UTCL0_STALL_UTCL1_REQ_OUT_OF_CREDITS   = 0x00000048,  // Total UTCL0 stalls due to out of credits for UTCL1 req
    TCP_PERF_SEL_CLIENT_UTCL0_INFLIGHT                  = 0x00000049,  // The sum of inflight client to UTCL0 requests per cycle
    TCP_PERF_SEL_UTCL0_UTCL1_INFLIGHT                   = 0x0000004a,  // The sum of inflight UTCL0_UTCL1 requests per cycle
    TCP_PERF_SEL_UTCL0_UTCL1_PERM_FAULT                 = 0x0000004b,  // Total UTCL0 to UTCL1 permission fault
    TCP_PERF_SEL_BACK_COMPAT_SWITCH                     = 0x0000004c,  // Count of cases where compatibility level changes back-to-back (split mode).
} TCP_PERFCOUNTER_SELECT;

typedef enum TD_PERFCOUNTER_SELECT : unsigned int {
    TD_PERF_SEL_none                                               = 0x00000000,  // Won't count anything.
    TD_PERF_SEL_td_busy                                            = 0x00000001,  // TD is processing or waiting for data.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_input_busy                                         = 0x00000002,  // TD input subblock is busy or waiting for data. This means the instruction, state or TC data fifos may not be empty or the TD is processing a wave.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_sampler_lerp_busy                                  = 0x00000003,  // TD filter subblock is busy, which means any of the four lerps has pixel data flowing down its pipeline (blend, accumulation, format).  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_sampler_out_busy                                   = 0x00000004,  // TD sampler output subblock is busy.  This means the TD's sampler output pipeline (accumulation, data swizzle, data packing) could be processing pixel data.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_nofilter_busy                                      = 0x00000005,  // TD no_filter subblock is busy.  This means the TD's no_filter pipeline (decode, format, data swizzle, data packing) could be processing non-sampler data.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_sampler_sclk_on_nofilter_sclk_off                  = 0x00000006,  // Number of cycles the sampler sclk is on while the no_filter sclk is off.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_nofilter_sclk_on_sampler_sclk_off                  = 0x00000007,  // Number of cycles the no_filter sclk is on while the sampler sclk is off.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_core_state_ram_max_cnt                             = 0x00000008,  // Denotes the maximum number of entries ever used in the TA_TD latency RAM for core state.  In order to get an accurate count, this counter must be enabled soon after reset.  Also, once the counter is read the value of the counter is no longer accurate.  A chip reset is required to get another accurate count.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_core_state_rams_read                               = 0x00000009,  // Number of times the RAMS that store core state are read.
    TD_PERF_SEL_weight_data_rams_read                              = 0x0000000a,  // Number of times the RAMs that store the weight data are read.
    TD_PERF_SEL_reference_data_rams_read                           = 0x0000000b,  // Number of times the RAMS that store the sample_c/gather4_c reference data are read.
    TD_PERF_SEL_tc_td_ram_fifo_full                                = 0x0000000c,  // TC_TD_ram input FIFO is full.  This counter could denote a stall in the TD pipeline, which could come from data cycling or power throttling from the SMU.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_tc_td_ram_fifo_max_cnt                             = 0x0000000d,  // Denotes the maximum number of TC_TD_ram requests ever stored in the TC_TD_ram fifo.  In order to get an accurate count, this counter must be enabled soon after reset.  Also, once the counter is read the value of the counter is no longer accurate.  A chip reset is required to get another accurate count.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_tc_td_data_fifo_full                               = 0x0000000e,  // TC_TD_data input FIFO is full.  This counter could denote a stall from either TD pipeline (sampler or no_filter), which could come from data cycling or power throttling from the SMU.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_input_state_fifo_full                              = 0x0000000f,  // TD input state FIFO is full.  This counter could denote there is no data from the TC or a stall in the TD pipeline.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_ta_data_stall                                      = 0x00000010,  // TD is stalled waiting for TA data.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_tc_data_stall                                      = 0x00000011,  // TD is stalled waiting for TC data.
    TD_PERF_SEL_tc_ram_stall                                       = 0x00000012,  // TD is stalled waiting for a TC ram request.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_lds_stall                                          = 0x00000013,  // TD is stalled because it has run out of credits and it has data waiting to be sent out to the LDS.
    TD_PERF_SEL_sampler_pkr_full                                   = 0x00000014,  // Both portions of the sampler's packer are full.  Could be caused by arbritation or lack of credits from the LDS.
    TD_PERF_SEL_nofilter_pkr_full                                  = 0x00000015,  // Both portions of the no_filter's packer is full.  Could be caused by arbritation or lack of credits from the LDS.
    TD_PERF_SEL_gather4_wavefront                                  = 0x00000016,  // Count the wavefronts with opcode = gather4, includes gather4_c.
    TD_PERF_SEL_gather4h_wavefront                                 = 0x00000017,  // Count the wavefronts with opcode = gather4h.
    TD_PERF_SEL_gather4h_packed_wavefront                          = 0x00000018,  // Count the wavefronts with opcode = gather4h_packed.
    TD_PERF_SEL_gather8h_packed_wavefront                          = 0x00000019,  // Count the wavefronts with opcode = gather8h_packed.
    TD_PERF_SEL_sample_c_wavefront                                 = 0x0000001a,  // Count the wavefronts with opcode = sample_c, includes gather4_c.
    TD_PERF_SEL_load_wavefront                                     = 0x0000001b,  // Count the wavefronts with opcode = load.  Includes atomics.
    TD_PERF_SEL_ldfptr_wavefront                                   = 0x0000001c,  // Count the wavefronts with LDFPTR formats.
    TD_PERF_SEL_RESERVED_29                                        = 0x0000001d,  // RESERVED_29
    TD_PERF_SEL_write_ack_wavefront                                = 0x0000001e,  // Count write acknowledgments (no data return).
    TD_PERF_SEL_d16_en_wavefront                                   = 0x0000001f,  // Count the wavefronts that use d16 conversion
    TD_PERF_SEL_bypassLerp_wavefront                               = 0x00000020,  // Count the sampler wavefronts that bypass the bilinear interpolator.  Includes gather4, point-sample instructions and unfilterable formats.
    TD_PERF_SEL_min_max_filter_wavefront                           = 0x00000021,  // Count the wavefronts that use min/max filtering.
    TD_PERF_SEL_one_comp_wavefront                                 = 0x00000022,  // dmask=1,2,4,8 (post d16 packing), one component wavefront sent to the LDS.
    TD_PERF_SEL_two_comp_wavefront                                 = 0x00000023,  // dmask=3,5,6,9,a,c (post d16 packing), two component wavefront sent to the LDS.
    TD_PERF_SEL_three_comp_wavefront                               = 0x00000024,  // dmask=7,b,d,e (post d16 packing), three component wavefront sent to the LDS.
    TD_PERF_SEL_four_comp_wavefront                                = 0x00000025,  // dmask=f (post d16 packing), four component wavefront sent to the LDS.
    TD_PERF_SEL_user_defined_border                                = 0x00000026,  // Count the wavefronts that user defined border color was used.
    TD_PERF_SEL_white_border                                       = 0x00000027,  // Count the wavefronts that white border color was used.
    TD_PERF_SEL_opaque_black_border                                = 0x00000028,  // Count the wavefronts that opaque black border color was used.
    TD_PERF_SEL_lod_warn_from_ta                                   = 0x00000029,  // Count the number of cycles the TA sends the TD at least one LOD warning.
    TD_PERF_SEL_wavefront_dest_is_lds                              = 0x0000002a,  // Count the number of times this TD sends data to the LDS.  This is a count of the LDS-only instructions, not all traffic on the TD_LDS_return interface.
    TD_PERF_SEL_td_cycling_of_nofilter_instr                       = 0x0000002b,  // Count the number of no-filter instructions where the TD has to cycle due to the data format and the number of available formatters.
    TD_PERF_SEL_tc_cycling_of_nofilter_instr                       = 0x0000002c,  // Count the number of no-filter instructions where the TC has to cycle data to the TD.
    TD_PERF_SEL_out_of_order_instr                                 = 0x0000002d,  // Count the number of out-of-order instructions from the TA.
    TD_PERF_SEL_total_num_instr                                    = 0x0000002e,  // The total number of instructions seen by this TD.
    TD_PERF_SEL_mixmode_instruction                                = 0x0000002f,  // For modes that align with the instruction, count the times the TD processes requests from the following compat levels:  GEN_TWO->GEN_ONE, GEN_ONE->GEN_TWO, GEN_TWO->GEN_ZERO, GEN_ZERO->GEN_TWO.  The instructions don't have to be back-to-back.  When the hardware is reset, the TD will bootup in GEN_TWO mode.
    TD_PERF_SEL_mixmode_resource                                   = 0x00000030,  // For modes that align with the resource, count the times the TD processes requests from the following compat levels:  GEN_TWO->GEN_ONE, GEN_ONE->GEN_TWO, GEN_TWO->GEN_ZERO, GEN_ZERO->GEN_TWO.  The instructions don't have to be back-to-back.  When the hardware is reset, the TD will bootup in GEN_TWO mode.
    TD_PERF_SEL_status_packet                                      = 0x00000031,  // Count the number of times a nack packet was generated and sent to the LDS.  Includes both nack and LOD warning packets.
    TD_PERF_SEL_address_cmd_poison                                 = 0x00000032,  // Count the wavefronts that had poisoned address or command.
    TD_PERF_SEL_data_poison                                        = 0x00000033,  // Count the wavefronts that had poisoned data.
    TD_PERF_SEL_done_scoreboard_max_stored_cnt                     = 0x00000034,  // Denotes the maximum amount of instructions that ever get stored in the TD done scoreboard.  In order to get an accurate count, this counter must be enabled soon after reset.  Also, once the counter is read the value of the counter is no longer accurate.  A chip reset is required to get another accurate count.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_done_scoreboard_max_waiting_cnt                    = 0x00000035,  // Denotes the maximum amount of instructions that have had their data sent to the LDS but their dones have not been sent.  In order to get an accurate count, this counter must be enabled soon after reset.  Also, once the counter is read the value of the counter is no longer accurate.  A chip reset is required to get another accurate count.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_done_scoreboard_not_empty                          = 0x00000036,  // TD done scoreboard fifo is not empty.  This fifo is used to reorder instructions so the dones leave the TD in-order.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_done_scoreboard_is_full                            = 0x00000037,  // TD done scoreboard fifo is full.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_done_scoreboard_bp_due_to_ooo                      = 0x00000038,  // TD done scoreboard is back pressured by out-of-order instructions.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_done_scoreboard_bp_due_to_lds                      = 0x00000039,  // TD done scoreboard is back pressured by lack of credits on the TD_LDS_return interface.  Perf_Windowing not supported for this counter.
    TD_PERF_SEL_nofilter_formatters_turned_on                      = 0x0000003a,  // Count the number of formatters in the no-filter pipeline that are not clock-gated off due to fixed destination selects and dmask.
    TD_PERF_SEL_nofilter_popcount_dmask_gt_num_comp_of_fmt         = 0x0000003b,  // Count the number of no-filter instructions that have a dmask with more components lit than the number of components of the data format.
    TD_PERF_SEL_nofilter_popcount_dmask_lt_num_comp_of_fmt         = 0x0000003c,  // Count the number of no-filter instructions that have a dmask with less components lit than the number of components of the data format.
    TD_PERF_SEL_msaa_load_wavefront                                = 0x0000003d,  // Count the wavefronts with opcode = msaa_load.
    TD_PERF_SEL_blend_prt_with_prt_default_0                       = 0x0000003e,  // Count the number of sampler instructions that enable blend_prt and the prt default is 0.
    TD_PERF_SEL_blend_prt_with_prt_default_1                       = 0x0000003f,  // Count the number of sampler instructions that enable blend_prt and the prt default is 1.
    TD_PERF_SEL_resmap_wavefront                                   = 0x00000040,  // Count the wavefronts that are residency maps.
    TD_PERF_SEL_prt_ack_wavefront                                  = 0x00000041,  // Count the number of wavefronts that are prt acks.  These acks could be residency maps or status maps.  The TD does not know when it gets the ack from the TA.
    TD_PERF_SEL_resmap_with_volume_filtering                       = 0x00000042,  // Count the number of pixels that have a residency map with volume filtering.
    TD_PERF_SEL_resmap_with_aniso_filtering                        = 0x00000043,  // Count the number of pixels that have a residency map with aniso filtering.
    TD_PERF_SEL_resmap_with_no_more_filtering                      = 0x00000044,  // Count the number of pixels that have a residency map that requires no extra filtering (neither volume or aniso).
    TD_PERF_SEL_resmap_with_cubemap_corner                         = 0x00000045,  // Count the number of pixels that have a residency map with a cubemap corner.
    TD_PERF_SEL_ray_tracing_bvh4_wavefront                         = 0x00000046,  // Count the wavefronts with opcode = bvh_intersect_ray.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_0        = 0x00000047,  // Number of times a bvh4 wavefront had no valid threads written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_1        = 0x00000048,  // Number of times a bvh4 wavefront had only 1 thread written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_2        = 0x00000049,  // Number of times a bvh4 wavefront had 2 threads total written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_3to4     = 0x0000004a,  // Number of times a bvh4 wavefront had 3 or 4 threads total written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_5to8     = 0x0000004b,  // Number of times a bvh4 wavefront had between 5 and 8 threads total written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_9to16    = 0x0000004c,  // Number of times a bvh4 wavefront had between 9 and 16 threads total written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_17to31   = 0x0000004d,  // Number of times a bvh4 wavefront had between 17 and 31 threads total written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_threads_per_wavefront_is_32       = 0x0000004e,  // Number of times a bvh4 wavefront had all 32 threads written out to LDS.
    TD_PERF_SEL_ray_tracing_bvh4_fp16_box_node                     = 0x0000004f,  // Count the number of FP16 box nodes seen in all bvh4 wavefronts.
    TD_PERF_SEL_ray_tracing_bvh4_fp32_box_node                     = 0x00000050,  // Count the number of FP32 box nodes seen in all bvh4 wavefronts.
    TD_PERF_SEL_ray_tracing_bvh4_tri_node                          = 0x00000051,  // Count the number of triangle nodes seen in all bvh4 wavefronts.
    TD_PERF_SEL_ray_tracing_bvh4_box_sort_en                       = 0x00000052,  // Count the number of bvh4 wavefronts that had box nodes that needed to be sorted.
    TD_PERF_SEL_ray_tracing_bvh4_box_grow_val_nonzero              = 0x00000053,  // Count the number of bvh4 wavefronts that had box nodes with non-zero grow values.
    TD_PERF_SEL_ray_tracing_bvh4_num_box_with_inf_or_nan_vtx       = 0x00000054,  // Count the number of boxes that have a vertex with the value of infinity or NaN.
    TD_PERF_SEL_ray_tracing_bvh4_num_tri_with_inf_or_nan_vtx       = 0x00000055,  // Count the number of triangles that have a vertex with the value of infinity or NaN.
    TD_PERF_SEL_ray_tracing_bvh4_num_box_that_squashed_a_nan       = 0x00000056,  // Count the number of boxes that had either their min or max value set to NaN (which will cause (min,max) to be set to (inf,-inf)).
    TD_PERF_SEL_ray_tracing_bvh4_num_box_misses                    = 0x00000057,  // Number of times a box node missed.
    TD_PERF_SEL_ray_tracing_bvh4_num_tri_misses                    = 0x00000058,  // Number of times a triangle node missed.
    TD_PERF_SEL_ray_tracing_bvh4_num_tri_tie_breakers              = 0x00000059,  // Number of times a triangle node missed due to a tie breaker.
    TD_PERF_SEL_ray_tracing_bvh4_pkr_full                          = 0x0000005a,  // Both portions of the bvh4's packer are full.  Could be caused by arbritation or lack of credits from the LDS.
    TD_PERF_SEL_ray_tracing_bvh4_busy                              = 0x0000005b,  // TD ray tracing subblock is busy.  This means the TD's raytracing pipeline (box and triangle test pipeline) could be processing pixel data.  Perf_Windowing not supported for this counter.
} TD_PERFCOUNTER_SELECT;

