typedef enum D3D12XBOX_COMMAND_QUEUE_PRIORITY
{
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_LOWEST  = 0x8,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_LOWER   = 0xa,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_LOW     = 0xd,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_MEDIUM  = 0x0,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_HIGH    = 0x3,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_HIGHER  = 0x5,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_HIGHEST = 0x7,
    D3D12XBOX_COMMAND_QUEUE_PRIORITY_DEFAULT = D3D12XBOX_COMMAND_QUEUE_PRIORITY_MEDIUM,
} D3D12XBOX_COMMAND_QUEUE_PRIORITY;

typedef enum D3D12_COMMAND_QUEUE_FLAGS
{
    D3D12_COMMAND_QUEUE_FLAG_NONE                 = 0,
    D3D12_COMMAND_QUEUE_FLAG_DISABLE_GPU_TIMEOUT  = 0x1,

    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_MASK    = 0x0f000000,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT   = 24,

    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_LOWEST  = D3D12XBOX_COMMAND_QUEUE_PRIORITY_LOWEST << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_LOWER   = D3D12XBOX_COMMAND_QUEUE_PRIORITY_LOWER << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_LOW     = D3D12XBOX_COMMAND_QUEUE_PRIORITY_LOW  << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_MEDIUM  = D3D12XBOX_COMMAND_QUEUE_PRIORITY_MEDIUM << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_HIGH    = D3D12XBOX_COMMAND_QUEUE_PRIORITY_HIGH << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_HIGHER  = D3D12XBOX_COMMAND_QUEUE_PRIORITY_HIGHER << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_HIGHEST = D3D12XBOX_COMMAND_QUEUE_PRIORITY_HIGHEST << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
    D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_DEFAULT = D3D12XBOX_COMMAND_QUEUE_PRIORITY_DEFAULT << D3D12XBOX_COMMAND_QUEUE_FLAG_PRIORITY_SHIFT,
} D3D12_COMMAND_QUEUE_FLAGS;

DEFINE_ENUM_FLAG_OPERATORS( D3D12_COMMAND_QUEUE_FLAGS );

