//
// Shader symbol information
// Returned in response to D3D12XBOX_PIPELINE_STATE_INFORMATION_TYPE_SYMBOL_TABLE
// The name pointers are valid while the pipeline state is alive
// The function pointers are valid while the pipeline state is alive
//

struct D3D12XBOX_SHADER_SYMBOL
{
    const char* pFunctionName;
    UINT    FunctionOffset;

    UINT    ScratchPerWaveInUnitsOf256DW : 16;
    UINT    ScratchPerLaneInDW : 16;
    UINT    LDSDwordsPerThreadgroup : 16;
    UINT    Reserved            : 16;
    UINT    NumVGPRs            : 9;
    UINT    HasIndirectCalls    : 1;
    UINT    EntryPoint          : 1;
    UINT    NumSGPRs            : 8;
};

struct D3D12XBOX_SHADER_SYMBOL_LIST
{
    const D3D12XBOX_SHADER_SYMBOL* pSymbols;
    D3D12_GPU_VIRTUAL_ADDRESS ShaderAllocationBase;
    UINT NumSymbols;
    UINT TotalShaderSize;
};


//
// Can be used to retrieve internal information about the Pipeline State Object
//
enum D3D12XBOX_PIPELINE_STATE_INFORMATION_TYPE
{
    D3D12XBOX_PIPELINE_STATE_INFORMATION_TYPE_SCRATCH_SIZE_PER_WAVE_IN_UNITS_OF_256DW,  // Return one UINT -- scratch size per wave in units of 1024B. If scratch size is 0 then it is disabled.
    D3D12XBOX_PIPELINE_STATE_INFORMATION_TYPE_SYMBOL_TABLE,                             // Returns shader's symbol table. Only compute is supported.
};

//
// Can be used to retrieve internal information about the Pipeline State Object. Raytracing doesn't know these until the callgraph is known
// so can't make these settings during the PSO create.
//
enum D3D12XBOX_PIPELINE_STATE_OPTION_TYPE
{
    D3D12XBOX_PIPELINE_STATE_OPTION_TYPE_ENABLE_USE_OF_PRIVATE_SCRATCH,          // Turns off SCRATCH_EN and expects the shader to call SetPrivateScratch function. Shader must not be in use during this call. Only compute is supported.
    D3D12XBOX_PIPELINE_STATE_OPTION_TYPE_SET_NUM_VGPRS,                          // Set the number of VGPRs for the entry point
    D3D12XBOX_PIPELINE_STATE_OPTION_TYPE_SET_LDS_SIZE_IN_DWORDS_PER_THREADGROUP, // Set the LDS size for the entry point
    D3D12XBOX_PIPELINE_STATE_OPTION_TYPE_SET_EXCP_EN,                            // Set TRAP_EN and other options
};

