//
union D3D12XBOX_RAYTRACING_INFORMATION
{
    // D3D12XBOX_RAYTRACING_INFORMATION_FLAG_GET_BASE_INFO
    struct
    {
        UINT    SftStackSize;               // Per-lane stack memory needed for the state function transform
        UINT    ScratchSize;                // Per-lane scratch memory needed for spill

        // Below fields are only valid in INSTRUMENTED builds
        UINT    LastRaysPerDispatch;
        UINT    LastNumDispatches;
    } BaseInfo;

    // D3D12XBOX_RAYTRACING_INFORMATION_FLAG_GET_SCRATCH_INFO
    struct
    {
        UINT    PerLaneSftStackSize;        // Per-lane stack memory needed for the state function transform
        UINT    PerLaneScratchSize;         // Per-lane scratch memory needed for spill
        UINT    WaveOccupancyLimit;         // Computed wave32 occupancy limit for the RTPSO (1 - 20)

        // The following value takes into account the wave occupancy limit and the number of SIMDs available.
        // It can be used to size a title-supplied scratch buffer for DispatchRaysX().
        UINT    SuggestedScratchSize;       // Total scratch memory needed to unthrottle DispatchRaysX
    } ScratchInfo;

    // D3D12XBOX_RAYTRACING_INFORMATION_FLAG_GET_EXPORT_TABLE -> D3D12XBOX_RAYTRACING_INFORMATION_EXPORTS
    ID3DBlob* GenericData;
};

enum D3D12XBOX_RAYTRACING_INFORMATION_FLAGS
{
    D3D12XBOX_RAYTRACING_INFORMATION_FLAG_GET_BASE_INFO,        // D3D12XBOX_RAYTRACING_INFORMATION::BaseInfo
    D3D12XBOX_RAYTRACING_INFORMATION_FLAG_GET_EXPORT_TABLE,     // D3D12XBOX_RAYTRACING_INFORMATION::GenericData
    D3D12XBOX_RAYTRACING_INFORMATION_FLAG_GET_SCRATCH_INFO      // D3D12XBOX_RAYTRACING_INFORMATION::ScratchInfo
};

